def caesar_cipher(text: str, shift: int) -> str:  
    result = []  
    for c in text:  
        if c.isalpha():  
            base = ord('A') if c.isupper() else ord('a')  
            new_ord = (ord(c) - base + shift) % 26 + base  
            result.append(chr(new_ord))  
        else:  
            result.append(c)  
    return ''.join(result)

def fibonacci(n: int) -> int:
    if n == 0:
        return 0
    elif n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        c = a + b
        a = b
        b = c
    return b

